The purple vertices are singular. The dashed line is
$\{\ell_{P}=0\}$. The red line is $\{\eta=0\}$, where 
\begin{align*}
\ell_{P} & =\frac{2509191}{8585347}+\frac{60144}{8585347}x-\frac{592758}{8585347}y,\\
\eta & =\max\left\{ \frac{9}{10}x+\frac{3}{8}y-\frac{11}{9},\;0\right\} \text{ such that }\mathbb{M}^{\mathrm{rel}}_{P}(\eta)<0.
\end{align*}

\label{prop: recharac Theta}Convex function $-\Theta_{P}$ is the
unique minimizer of functional 
\begin{equation}
\Psi(\eta)\coloneqq\frac{1}{2}\int_{P}\eta^{2}\mathrm{d}x+\int_{\partial P}\eta\ \mathrm{d}\sigma,\ \eta\in\mathcal{C}_{1}(P)\cap L^{2}(P).\label{eq: Inoue functional}
\end{equation}

\label{thm: min Psi_k} Functional $\Psi_{k}$ admits a unique minimizer
\begin{equation}
\psi_{k}\coloneqq2V_{P}k^{n+1}\sigma^{\vee}_{k}-2k.\label{eq:quan minimizer}
\end{equation}

Given a lattice polytope $P$, there exists a constant $C_{P}>0$
(depending on $P$) such that for any $k\ge1$, there exists a triangulation
$T$ of $(P,P_{k})$ with GKZ vector $g_{T}\le C_{P}k^{-n}$. Then
for any convex function $\phi\ge0$ on $P$, we have 
\begin{equation}
\fint_{P}\phi\mathrm{d}x\le\frac{C_{P}}{k^{n}}\sum_{u\in P_{k}}\phi(u).\label{eq:rough bound}
\end{equation}

\label{thm-fine}
For a Delzant lattice polytope $P$, there exists constant $C_{1},C_{2},C_{b}>0$
and $k_{0}$ (all only depend on $P$) such that for any $0\le\phi\in\mathcal{C}(P)$
and $k>k_{0}$, we have 
\begin{equation}
k^{n}\int_{P}\phi\le\sum_{u\in P_{k}}2^{-\mathrm{cd}(u)}\phi(u)+\frac{C_{1}}{k}\sum_{u\in P_{k}\cap\partial P}\phi(u)+\frac{C_{2}}{k^{2}}\sum_{u\in P_{k}}\phi(u),\label{eq:key estimate}
\end{equation}
where $\mathrm{cd}(u)$ is the number of facets containing $u$. Apply it to each facet, we obtain 
\begin{equation}
k^{n-1}\int_{\partial P}\phi\mathrm{d}\sigma\le\left(1+\frac{C_{b}}{k}\right)\sum_{u\in P_{k}\cap\partial P}\phi(u).\label{eq: b key estimate}
\end{equation}

Fix a point $x_{0}\in\mathrm{int}P$. There exists a constant $C_{\pi}(P,x_{0})>0$
such that 
\begin{equation}
\left\Vert \phi\right\Vert _{k}\le C_{\pi}\left\Vert \phi-\pi_{k}\phi\right\Vert _{k}\label{eq:projection control}
\end{equation}
holds for all normalized convex functions at $x_{0}$.

\label{prop: Donaldson compact}Let $P$ be a lattice polytope with
a point $x_{0}\in\mathrm{int}P$. If $\phi_{k}\in\mathcal{C}(P)$
is a sequence of normalized convex functions such that $\int_{\partial P}\phi_{k}\mathrm{d}\sigma\le C$,
then there exists a subsequence locally uniformly converges to a function
$\phi\in\mathcal{C}_{1}(P)$, and 
\begin{equation}
\int_{\partial P}\phi\mathrm{d}\sigma\le\liminf_{k}\int_{\partial P}\phi_{k}\mathrm{d}\sigma.\label{eq: Donald liminf}
\end{equation}

Let $P\subset\mathbb{R}^{n}$ be a lattice polytope. For any $k\in\mathbb{Z}_{>0}$,
set $P_{k}=P\cap k^{-1}\mathbb{Z}^{n}$. Let $f_{k}:P\rightarrow\mathbb{R}$
be a sequence of convex functions (continuous up to $\partial P$)
which uniformly converges to $f$. Then we have 
\begin{equation}
\lim_{k\rightarrow\infty}\frac{1}{k^{n-1}}\left(\sum_{u\in P_{k}}f_{k}(u)-k^{n}\int_{P}f_{k}\ \mathrm{d}x\right)=\frac{1}{2}\int_{\partial P}f\ \mathrm{d}\sigma.\label{eq:EM enhanced}
\end{equation}
In particular, when $f_{k}=f$ for all $k$, we have expansion 
\begin{equation}
\sum_{u\in P_{k}}f(u)=k^{n}\int_{P}f\ \mathrm{d}x+\frac{k^{n-1}}{2}\int_{\partial P}f\ \mathrm{d}\sigma+\mathrm{o}(k^{n-1}).\label{eq:EM}
\end{equation}
In the above, $\mathrm{d}x$ is the standard Lebesgue measure, and
the boundary measure $\mathrm{d}\sigma$ is defined as follows. For
each facet $F\subset\partial P$ spanning affine subspace $\mathrm{Aff}(F)$,
$\mathrm{d}\sigma|_{F}$ is the Lebesgue measure normalized by the
lattice $\mathrm{Aff}(F)\cap\mathbb{Z}^{n}$.
